<?php
declare(strict_types=1);
namespace App\Modules\CommercialRental\Models;
use App\Core\Database;
final class CommercialRentalRequest{private Database$db;public function __construct(){$this->db=app()->get('db');}public function all(int$t):array{return$this->db->fetchAll("SELECT r.*,b.name provider_name,v.name vehicle_name,c.name category_name FROM commercial_rental_requests r LEFT JOIN commercial_rental_providers p ON p.id=r.provider_id AND p.tenant_id=r.tenant_id LEFT JOIN businesses b ON b.id=p.business_id AND b.tenant_id=p.tenant_id LEFT JOIN commercial_rental_vehicles v ON v.id=r.vehicle_id AND v.tenant_id=r.tenant_id LEFT JOIN commercial_rental_categories c ON c.id=v.category_id AND c.tenant_id=v.tenant_id WHERE r.tenant_id=? AND r.deleted_at IS NULL ORDER BY r.id DESC",[$t]);}public function find(int$t,int$id):?array{return$this->db->fetch("SELECT r.*,b.name provider_name,v.name vehicle_name FROM commercial_rental_requests r LEFT JOIN commercial_rental_providers p ON p.id=r.provider_id AND p.tenant_id=r.tenant_id LEFT JOIN businesses b ON b.id=p.business_id AND b.tenant_id=p.tenant_id LEFT JOIN commercial_rental_vehicles v ON v.id=r.vehicle_id AND v.tenant_id=r.tenant_id WHERE r.tenant_id=? AND r.id=? AND r.deleted_at IS NULL",[$t,$id]);}public function create(int$t,array$d,int$u):int{$this->db->execute("INSERT INTO commercial_rental_requests(uuid,tenant_id,member_id,provider_id,vehicle_id,request_no,customer_name,customer_phone,purpose,pickup_address,pickup_lat,pickup_lng,destination_address,destination_lat,destination_lng,start_at,end_at,duration_text,operator_required,status,quoted_amount,final_amount,customer_notes,admin_notes,created_by,updated_by) VALUES(UUID(),?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",[$t,$d['member_id'],$d['provider_id'],$d['vehicle_id'],$d['request_no'],$d['customer_name'],$d['customer_phone'],$d['purpose'],$d['pickup_address'],$d['pickup_lat'],$d['pickup_lng'],$d['destination_address'],$d['destination_lat'],$d['destination_lng'],$d['start_at'],$d['end_at'],$d['duration_text'],$d['operator_required'],$d['status'],$d['quoted_amount'],$d['final_amount'],$d['customer_notes'],$d['admin_notes'],$u,$u]);return(int)$this->db->lastInsertId();}public function update(int$t,int$id,array$d,int$u):void{$this->db->execute("UPDATE commercial_rental_requests SET member_id=?,provider_id=?,vehicle_id=?,customer_name=?,customer_phone=?,purpose=?,pickup_address=?,pickup_lat=?,pickup_lng=?,destination_address=?,destination_lat=?,destination_lng=?,start_at=?,end_at=?,duration_text=?,operator_required=?,status=?,quoted_amount=?,final_amount=?,customer_notes=?,admin_notes=?,updated_by=? WHERE tenant_id=? AND id=? AND deleted_at IS NULL",[$d['member_id'],$d['provider_id'],$d['vehicle_id'],$d['customer_name'],$d['customer_phone'],$d['purpose'],$d['pickup_address'],$d['pickup_lat'],$d['pickup_lng'],$d['destination_address'],$d['destination_lat'],$d['destination_lng'],$d['start_at'],$d['end_at'],$d['duration_text'],$d['operator_required'],$d['status'],$d['quoted_amount'],$d['final_amount'],$d['customer_notes'],$d['admin_notes'],$u,$t,$id]);}public function addStatusHistory(int$t,int$id,?string$oldStatus,string$newStatus,int$u,?string$notes=null):void{$this->db->execute("INSERT INTO commercial_rental_request_status_history (tenant_id,request_id,old_status,new_status,changed_by,actor_type,notes) VALUES (?,?,?,?,?, 'ADMIN', ?)",[$t,$id,$oldStatus,$newStatus,$u,$notes]);}public function delete(int$t,int$id,int$u):void{$this->db->execute("UPDATE commercial_rental_requests SET deleted_at=NOW(),updated_by=? WHERE tenant_id=? AND id=? AND deleted_at IS NULL",[$u,$t,$id]);}public function nextNo(int$t):string{$r=$this->db->fetch("SELECT id FROM commercial_rental_requests WHERE tenant_id=? ORDER BY id DESC LIMIT 1",[$t]);$n=((int)($r['id']??0))+1;return'CR-'.date('Ym').'-'.str_pad((string)$n,5,'0',STR_PAD_LEFT);}public function countByStatus(int$t,string$s):int{$r=$this->db->fetch("SELECT COUNT(*) c FROM commercial_rental_requests WHERE tenant_id=? AND status=? AND deleted_at IS NULL",[$t,$s]);return(int)($r['c']??0);}}
